-- Resources content for retiring Sourcework's earlier research steps (CLAUDE.md, "Resources stay in step with the code").
-- Content only; no schema. Depends on 20261024120000.

select private.rc_release_guide(
  p_slug => 'sourcework-research-prompts',
  p_tool_key => 'transcription',
  p_title => 'Maintaining the research prompts',
  p_summary => 'For editors: edit the wording, publish and roll back.',
  p_screen_keys => array['sourcework.editors'],
  p_sort_order => 20,
  p_version_note => 'The earlier research prompts are retired',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Editors maintain the wording the research steps use. You need the Editor role on Sourcework, which an administrator grants on the user’s access screen."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Edit a prompt"}]},{"type":"paragraph","content":[{"type":"text","text":"Open Research prompts from the Projects page. Choose Analyze guide, Synthesis guide or Outline guide, edit the text and it saves itself as a draft only you can see. The wording decides what makes a finding worth keeping and a clip worth offering, how a synthesis weighs the findings, and what makes a good outline. The shape of the answer is fixed by the code, and What the model is given and returns shows both."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Publish and roll back"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Publish… asks for a one-line note about what changed, then makes the draft the live version for every project."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"History lists earlier versions, with the share of findings people accepted for the Analyze guide. Make live again moves an earlier version back into use. Nothing is deleted."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-themes',
  p_tool_key => 'transcription',
  p_title => 'Themes',
  p_summary => 'Decide on suggested themes, write your own, and read the evidence for and against each one.',
  p_screen_keys => array['sourcework.themes', 'sourcework.theme'],
  p_sort_order => 21,
  p_version_note => 'Review themes and automatic filing are retired',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A theme is a statement that your project’s sources bear out or push against, such as “Locals treated the fort’s tunnels as a private playground”. A topic such as “Childhood” is not a theme. Themes show how broadly something is backed, and they keep the evidence against it beside the evidence for it. Nothing proposes themes any more; the tab lists the ones you write yourself and any made by earlier runs, and Synthesis is how a project reaches an answer."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Open the Themes tab"}]},{"type":"paragraph","content":[{"type":"text","text":"Open a project and select Themes. The tab appears only on projects that already have themes. Its badge counts the suggestions waiting for you. Waiting for you lists data points still to review in each source, and suggestions left by earlier runs to decide on."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Decide on suggested themes"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Accept keeps a suggestion. Reject hides it, and it is not proposed again. Put back for review is under the Rejected filter."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Edit opens the theme to reword it. Saving a suggestion accepts it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A suggestion marked Reads like a topic is a subject heading rather than a claim. Edit it into a sentence that says something."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A theme marked Single source is backed by one source only. That is a flag, not a verdict."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A merge suggestion says two themes are the same claim in different words. Accepting moves the data points across and records why in the memo of the theme that stays."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"How a data point gets into a theme"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"By hand: on a theme’s page, Add data points lists accepted data points that are not in it. The ⋮ beside a piece of evidence changes it between supporting and complicating, or removes it. A removed data point stays removed."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"To make a theme yourself, choose + New theme on the Themes tab. Nothing is filed into it for you."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The theme page"}]},{"type":"paragraph","content":[{"type":"text","text":"Open a theme to read its evidence by source, with supporting and complicating data points side by side. Select the play button to open the source at that passage. Breadth shows how many of the project’s sources and speakers back the theme. The memo is yours: no run reads or changes it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only accepted data points count toward a theme. Un-accepting one removes it from the numbers without deleting it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Everything here works on a phone: the table becomes cards and the evidence stacks."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-suggested-quotes',
  p_tool_key => 'transcription',
  p_title => 'Suggested quotes',
  p_summary => 'Play, trim, accept or reject clips the model left waiting for you.',
  p_screen_keys => array['sourcework.theme_quotes', 'sourcework.theme'],
  p_sort_order => 22,
  p_version_note => 'Suggest quotes is retired',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Suggested quotes are clips the model picked for you to play and decide on. A data point is a paraphrase of what someone said; a quote is a literal cut of the recording that would work on air. Nothing becomes an excerpt until you accept it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Where clips come from"}]},{"type":"paragraph","content":[{"type":"text","text":"Analyzing a source proposes up to five clips on that source’s own page, under Clips to review. This screen lists the clips an earlier run left waiting on a theme. Nothing on a theme asks for more; there is no Suggest quotes button any more."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Decide on each clip"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each card shows how strong the clip is (Strong, Good or Usable), who says it, the words, its length and why it works. A clip marked Complicates comes only from data points that push against the theme; it is there as the counterweight."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Play","marks":[{"type":"bold"}]},{"type":"text","text":" plays the clip as it will cut, from the original audio. Check the words as you listen: the transcript is itself a machine reading of the audio."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Accept","marks":[{"type":"bold"}]},{"type":"text","text":" saves the clip as an ordinary excerpt on its source, linked to the data points it rests on. It then appears in the theme’s Excerpts panel, on the project’s Excerpts tab and in the piece editor."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Trim","marks":[{"type":"bold"}]},{"type":"text","text":" opens the start and end with the −250, −50, +50 and +250 buttons. Play again to hear the new cut, then Accept. The words are read again from the transcript for the range you accept."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reject","marks":[{"type":"bold"}]},{"type":"text","text":" hides the clip. It is kept, so the same stretch is not suggested again."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Clips are only ever taken from the speaker’s own words, one speaker at a time, at sentence edges."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Everything here works on a phone: cards stack, and the buttons are larger."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-accept-in-bulk',
  p_tool_key => 'transcription',
  p_title => 'Accepting suggestions in bulk',
  p_summary => 'Accept every waiting data point, theme or suggested quote at once instead of one by one.',
  p_screen_keys => array['sourcework.themes', 'sourcework.theme_quotes', 'sourcework.source'],
  p_sort_order => 24,
  p_version_note => 'Accepted data points are no longer filed automatically',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When the model has suggested a lot, you do not have to decide on each one separately. Three screens have an accept-all button. It asks you to confirm first, because you are deciding on many things without reading each."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Data points"}]},{"type":"paragraph","content":[{"type":"text","text":"On a source, with the To review filter showing, Accept all accepts every data point in that source still waiting for review. On the project’s Themes tab, the Waiting for you panel has the same button for every source in the project."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Themes"}]},{"type":"paragraph","content":[{"type":"text","text":"On the Themes tab, "},{"type":"text","text":"Accept all suggested","marks":[{"type":"bold"}]},{"type":"text","text":" accepts every suggested theme as it is worded. Merge suggestions are a separate decision and keep their own Accept and Reject buttons. If a theme reads like a topic, reword it first with Edit."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Suggested quotes"}]},{"type":"paragraph","content":[{"type":"text","text":"On a theme’s suggested quotes, "},{"type":"text","text":"Accept all","marks":[{"type":"bold"}]},{"type":"text","text":" saves the waiting clips as excerpts, each at the cut the model suggested. To use a trimmed cut, accept that clip on its own. Up to 30 clips are accepted at a time; if more are waiting, accept again. A clip that cannot be accepted stays in the list."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Taking a decision back"}]},{"type":"paragraph","content":[{"type":"text","text":"Nothing is deleted by accepting. A data point can be rejected or put back for review, a theme rejected from its page, and an accepted quote’s excerpt deleted like any other."}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-pieces',
  p_tool_key => 'transcription',
  p_title => 'Building a piece from narration and excerpts',
  p_summary => 'Write a wrap, voicer or feature block by block, or draft it from a format, then edit by hand or with the assistant. Every version is kept.',
  p_screen_keys => array['sourcework.pieces', 'sourcework.piece'],
  p_sort_order => 18,
  p_version_note => 'Wording matches the retired research steps',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A piece is a reader, voicer, wrap, spot or feature you build from your own narration and the project's excerpts. It starts blank. You can write it block by block, or let AI draft a first version from a format and then edit it by hand or with the assistant."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Start a piece"}]},{"type":"paragraph","content":[{"type":"text","text":"Open a project, select "},{"type":"text","text":"Pieces","marks":[{"type":"bold"}]},{"type":"text","text":", pick a format if you want one (or leave it on No format), then "},{"type":"text","text":"+ New piece","marks":[{"type":"bold"}]},{"type":"text","text":". The editor opens at once on an empty piece with its title ready to type. The Pieces list shows each piece's length and when it last changed."}]},{"type":"paragraph","content":[{"type":"text","text":"A format sets the piece's target length and gives you a guide to write by. You can choose or change it any time from "},{"type":"text","text":"Format","marks":[{"type":"bold"}]},{"type":"text","text":" under the length at the top of the piece, and "},{"type":"text","text":"Show guide","marks":[{"type":"bold"}]},{"type":"text","text":" shows its description. The guide is a reminder of what the format usually asks for; it doesn't stop you doing something else. Choosing a format doesn't change what you've written."}]},{"type":"paragraph","content":[{"type":"text","text":"The formats are Reader / Voicer (about 0:30 to 0:45, no recorded excerpts), Cut and Copy (0:45, one excerpt), Wrap (about 0:45 to 1:00, one or two), Super Spot (2:00, one to three) and Feature (4:00, two to six). The excerpt counts are a usual range, not a requirement: a strong piece can use fewer."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Draft with AI (optional)"}]},{"type":"paragraph","content":[{"type":"text","text":"On an empty piece, choose "},{"type":"text","text":"Draft with AI","marks":[{"type":"bold"}]},{"type":"text","text":". Pick a format, such as Wrap, which sets the length, the usual number of actualities and a free-text description. The model decides how much narration the story needs and which excerpts to place; the format is a set of guardrails, not a block-by-block outline. Under Material, the project's accepted themes are all ticked; untick any you want left out. Suggested themes are listed but can't be used until someone accepts them. Add a direction if you like, then choose "},{"type":"text","text":"Generate draft","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"It takes a minute or two. The model writes the narration only. Every actuality is one of the project's excerpts, placed by the code, so the words and the audio are always the speaker's own. It works only from accepted themes, their accepted data points and the project's excerpts, and it leaves a bracketed note such as [CHECK: year] where the material doesn't say something it needs."}]},{"type":"paragraph","content":[{"type":"text","text":"You land back in the editor with the draft in place and a note saying which format drafted it and its length. "},{"type":"text","text":"Undo","marks":[{"type":"bold"}]},{"type":"text","text":" on that note puts the piece back as it was. Draft with AI is offered only on an empty piece; to start over later, ask the assistant. A piece with no target length takes the format's."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Add narration and excerpts"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Narration","marks":[{"type":"bold"}]},{"type":"text","text":". Write in a narration block. Press Enter at the end of a block to add another below it, and Shift+Enter for a new line. Backspace in an empty block removes it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Excerpts","marks":[{"type":"bold"}]},{"type":"text","text":". Between every block, and before the first and after the last, there is a + row. Select it and choose Excerpt to search the project's audio excerpts by title, words, speaker or source. Arrow keys move through the results and Enter adds one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An excerpt's words always come from the transcript for the clip you hear. They cannot be retyped in the piece."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Edit a block"}]},{"type":"paragraph","content":[{"type":"text","text":"Select the ⋮ beside a block for "},{"type":"text","text":"Move up","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Move down","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Mark as anchor intro","marks":[{"type":"bold"}]},{"type":"text","text":" (on narration), "},{"type":"text","text":"Swap excerpt…","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Trim…","marks":[{"type":"bold"}]},{"type":"text","text":" and removal. On a desktop you can also drag the ⋮⋮ handle to reorder."}]},{"type":"paragraph","content":[{"type":"text","text":"An "},{"type":"text","text":"anchor intro","marks":[{"type":"bold"}]},{"type":"text","text":" is the lead-in the anchor reads before a reporter's recorded piece. It is shown as its own block and isn't counted in the piece's length, so a 0:53 wrap stays 0:53 whatever the intro adds. Reader, voicer and cut and copy copy is part of the piece and is timed with it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Trim a clip in place"}]},{"type":"paragraph","content":[{"type":"text","text":"Choose "},{"type":"text","text":"Trim…","marks":[{"type":"bold"}]},{"type":"text","text":" on an excerpt block. The clip's words appear in their transcript context. Tap a word to move the nearer end of the clip there, or nudge the start and end with the −250, −50, +50 and +250 buttons. "},{"type":"text","text":"Play as cut","marks":[{"type":"bold"}]},{"type":"text","text":" plays what you have."}]},{"type":"paragraph","content":[{"type":"text","text":"By default a trim belongs to this piece only and the excerpt itself is unchanged. Choose "},{"type":"text","text":"Update the excerpt everywhere","marks":[{"type":"bold"}]},{"type":"text","text":" to change the excerpt itself; the panel says how many other pieces use it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Length"}]},{"type":"paragraph","content":[{"type":"text","text":"The length at the top adds up narration, estimated at 160 words a minute, and the clips' own running time, without any anchor intro. Choosing a format sets a target; select "},{"type":"text","text":"Change target","marks":[{"type":"bold"}]},{"type":"text","text":" to use a different one. The piece shows how far under or over it is."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Ask the assistant"}]},{"type":"paragraph","content":[{"type":"text","text":"Open the assistant from "},{"type":"text","text":"Assistant","marks":[{"type":"bold"}]},{"type":"text","text":" at the top of the piece (on a phone, the bar at the bottom). It knows which piece you have open and says so at the top: “Working in: …”. Ask it to tighten a passage, move a quote, trim a clip, add a line, or start over from a format. Anything you have typed is saved before your message goes."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"It changes only what you ask, and says what it changed. Its reply lists the tools it used."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"It places and swaps excerpts by id. It can't change what a speaker said, and the lengths it reports come from the same arithmetic as the screen."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each block it changed is marked "},{"type":"text","text":"Edited by the assistant","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"Added by the assistant","marks":[{"type":"bold"}]},{"type":"text","text":". "},{"type":"text","text":"Undo","marks":[{"type":"bold"}]},{"type":"text","text":" on the mark puts that block back. The marks stay until you next edit the piece yourself."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"From a + row, Ask the assistant to write it opens the assistant with a request for narration at that spot, for you to finish and send."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Saving and history"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A piece saves itself a moment after you stop typing. Every save is a version, including each change the assistant makes and every draft."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"History lists the versions with who saved each one, and whether it was you, Draft with AI or the assistant. Restore saves an earlier version again as the newest, so nothing is lost."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If someone else saves the piece while you are editing, you are asked to reload instead of overwriting their work."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Take it with you"}]},{"type":"paragraph","content":[{"type":"text","text":"Copy as text","marks":[{"type":"bold"}]},{"type":"text","text":" copies the narration and the quoted words, with each clip's length and the total running time. "},{"type":"text","text":"Export excerpts","marks":[{"type":"bold"}]},{"type":"text","text":" downloads every excerpt in the project as one zip."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only audio and video excerpts can go in a piece. Document excerpts have no sound."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If an excerpt is deleted after it was used, its block says so and can be swapped or removed."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Everything on a piece works on a phone: menus and the + picker open as sheets, and Move up and Move down replace dragging."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Drafting and the assistant send the piece's material (accepted themes, data points and the excerpts' words) to an outside service, as analysis does. Building a piece by hand doesn't."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Pieces list says how each piece was made: Written by hand, or the format that drafted it, then edited."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-25-sourcework-retire-old-pipeline',
  p_tool_key => 'transcription',
  p_released_on => '2026-10-25',
  p_title => 'Sourcework: The earlier research steps are retired',
  p_guide_slugs => array['sourcework-research-prompts','sourcework-themes','sourcework-suggested-quotes','sourcework-accept-in-bulk'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sourcework no longer runs the earlier research steps. Analyze on a source, Synthesize on a project and Outline on a piece are how the work now goes. Accepting a data point no longer files it into themes by itself, Review themes and Suggest quotes are gone, and the Research prompts screen keeps the Analyze, Synthesis and Outline guides. Themes you wrote, themes earlier runs made, and clips already waiting are all still there to decide on."}]}]}$body$
);
